 public sealed class PriceCalculator
 {
     public decimal CalculateTotal(decimal unitPrice, int quantity, decimal taxRate)
     {
         if (quantity < 0)
             throw new ArgumentOutOfRangeException(nameof(quantity), "Quantity cannot be negative.");
